function VWalkJson($e,[string]$kind){if($e.ValueKind-ceq[Text.Json.JsonValueKind]::Object){$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($q in $e.EnumerateObject()){Req($seen.Add($q.Name))"duplicate $kind member";VWalkJson $q.Value $kind}}elseif($e.ValueKind-ceq[Text.Json.JsonValueKind]::Array){foreach($q in $e.EnumerateArray()){VWalkJson $q $kind}}}
