function ReadVControl($path,[ValidateSet('pointer','manifest')]$kind){$text=gc -Raw -LiteralPath $path;try{$doc=[Text.Json.JsonDocument]::Parse($text)}catch{Req $false "$kind json"};try{$e=$doc.RootElement;VWalkJson $e $kind;$top=if($kind-ceq'pointer'){@('schema','run_instance_id','version_path','manifest_sha256')}else{@('schema','run_instance_id','status','evidence_class','files','sources')};VExactJson $e $top $kind;foreach($n in $top){$p=$e.GetProperty($n);if($kind-ceq'manifest'-and$n-in@('files','sources')){Req($p.ValueKind-ceq[Text.Json.JsonValueKind]::Object)'manifest scalar'}else{Req($p.ValueKind-ceq[Text.Json.JsonValueKind]::String)"$kind scalar"}};if($kind-ceq'manifest'){foreach($pair in @(@('files',@('config.json','decision-contract.json','raw.json')),@('sources',@('config.json','decision-contract.json','run-wp4-decision.ps1','oracle/wp4-oracle.py')))){$o=$e.GetProperty($pair[0]);VExactJson $o $pair[1] manifest;foreach($p in $o.EnumerateObject()){Req($p.Value.ValueKind-ceq[Text.Json.JsonValueKind]::String)'manifest scalar'}}}}finally{$doc.Dispose()};$text|ConvertFrom-Json}
