function FitLogistic($rows){$a=0.;$b=0.;for($it=0;$it-lt50;$it++){$g0=$g1=$h00=$h01=$h11=0.;foreach($r in $rows){$p=1/(1+[Math]::Exp(-($a+$b*$r.score)));$w=$p*(1-$p);$g0+=$r.event-$p;$g1+=($r.event-$p)*$r.score;$h00+=$w;$h01+=$w*$r.score;$h11+=$w*$r.score*$r.score};$det=$h00*$h11-$h01*$h01;Req($det-gt1e-12)'logistic separation';$da=($h11*$g0-$h01*$g1)/$det;$db=(-$h01*$g0+$h00*$g1)/$det;$a+=$da;$b+=$db;if([Math]::Max([Math]::Abs($da),[Math]::Abs($db))-lt1e-10){return [pscustomobject]@{intercept=$a;slope=$b}}};throw'logistic convergence'}
